    {
      "name": "Finset.sum_erase_lt_of_pos",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {κ : Type u_5} [inst : DecidableEq ι] [inst_1 : AddCommMonoid κ] [inst_2 : LT κ] [AddLeftStrictMono κ]\n  {s : Finset ι} {d : ι}, d ∈ s → ∀ {f : ι → κ}, 0 < f d → ∑ m ∈ s.erase d, f m < ∑ m ∈ s, f m"
    },
    {
      "name": "Finset.sum_lt_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedCancelAddMonoid M]\n  {f g : ι → M} {s : Finset ι}, (∀ i ∈ s, f i ≤ g i) → (∃ i ∈ s, f i < g i) → ∑ i ∈ s, f i < ∑ i ∈ s, g i"
    },
    {
      "name": "ENNReal.sum_lt_sum_of_nonempty",
      "module_name": "Mathlib.Data.ENNReal.BigOperators",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {s : Finset α}, s.Nonempty → ∀ {f g : α → ENNReal}, (∀ i ∈ s, f i < g i) → ∑ i ∈ s, f i < ∑ i ∈ s, g i"
    },
    {
      "name": "List.sum_lt_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.List",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_3} [inst : AddMonoid M] [inst_1 : Preorder M] [AddLeftStrictMono M] [AddLeftMono M]\n  [AddRightStrictMono M] [AddRightMono M] {l : List ι} (f g : ι → M),\n  (∀ (i : ι), i ∈ l → f i ≤ g i) → (∃ i, i ∈ l ∧ f i < g i) → (List.map f l).sum < (List.map g l).sum"
    },
    {
      "name": "Finset.single_lt_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedCancelAddMonoid M]\n  {f : ι → M} {s : Finset ι} {i j : ι},\n  j ≠ i → i ∈ s → j ∈ s → 0 < f j → (∀ k ∈ s, k ≠ i → 0 ≤ f k) → f i < ∑ k ∈ s, f k"
    }
  ]
}
